### Steps to reproduce issue

Run the program below (needs `rclcpp` and `std_msgs`). It checks two things per executor:

1. Five subscriptions with one pending message each, then one `spin_some()` / `spin_all(0)`.
2. A subscription created after its callback group was added to the executor, with one pending message.

<details>
<summary>main.cpp</summary>

```cpp
#include <chrono>
#include <cstdio>
#include <memory>
#include <string>
#include <thread>
#include <vector>

#include "rclcpp/rclcpp.hpp"
#include "rclcpp/executors/events_cbg_executor/events_cbg_executor.hpp"
#include "std_msgs/msg/int32.hpp"

using namespace std::chrono_literals;
using Int32 = std_msgs::msg::Int32;

// 1) Five subscriptions with one message pending on each, then ONE spin call.
//    Returns the number of callbacks that ran.
template<typename ExecutorT>
int ready_subscriptions(bool use_spin_all)
{
  ExecutorT exec;
  auto node = std::make_shared<rclcpp::Node>("ready_node");
  int ran = 0;
  std::vector<rclcpp::Subscription<Int32>::SharedPtr> subs;
  std::vector<rclcpp::Publisher<Int32>::SharedPtr> pubs;
  for (int i = 0; i < 5; ++i) {
    const auto topic = "ready_" + std::to_string(i);
    subs.push_back(node->create_subscription<Int32>(topic, 10, [&](Int32::ConstSharedPtr) {++ran;}));
    pubs.push_back(node->create_publisher<Int32>(topic, 10));
  }
  exec.add_node(node);
  exec.spin_all(500ms);  // settle
  for (auto & pub : pubs) {
    pub->publish(Int32());
  }
  std::this_thread::sleep_for(500ms);  // every message has arrived
  if (use_spin_all) {
    exec.spin_all(0ns);
  } else {
    exec.spin_some();
  }
  return ran;
}

// 2) Subscription created AFTER its callback group was added to the executor, one message
//    pending. Returns the number of spin_some() calls until the callback ran.
template<typename ExecutorT>
int late_subscription()
{
  ExecutorT exec;
  auto node = std::make_shared<rclcpp::Node>("late_node");
  auto group = node->create_callback_group(rclcpp::CallbackGroupType::MutuallyExclusive, false);
  exec.add_callback_group(group, node->get_node_base_interface());

  bool ran = false;
  rclcpp::SubscriptionOptions options;
  options.callback_group = group;
  auto sub = node->create_subscription<Int32>("late", 10, [&](Int32::ConstSharedPtr) {ran = true;}, options);
  auto pub = node->create_publisher<Int32>("late", 10);
  while (pub->get_subscription_count() == 0) {
    std::this_thread::sleep_for(10ms);
  }
  pub->publish(Int32());
  std::this_thread::sleep_for(500ms);

  int calls = 0;
  while (!ran && calls < 10) {
    exec.spin_some();
    ++calls;
  }
  return calls;
}

template<typename ExecutorT>
void check(const char * name)
{
  std::printf("%-24s spin_some(): %d/5   spin_all(0): %d/5   late subscription: %d spin_some() call(s)\n",
    name, ready_subscriptions<ExecutorT>(false), ready_subscriptions<ExecutorT>(true),
    late_subscription<ExecutorT>());
}

int main(int argc, char ** argv)
{
  rclcpp::init(argc, argv);
  check<rclcpp::executors::SingleThreadedExecutor>("SingleThreadedExecutor");
  check<rclcpp::executors::EventsCBGExecutor>("EventsCBGExecutor");
  rclcpp::shutdown();
}
```

</details>

### Expected behavior

One call runs all five callbacks: `spin_some()` documents a `max_duration` of 0 as "all of the collected work will be executed", and `spin_all(0)` runs until no work is left. 

### Actual behavior

```
SingleThreadedExecutor   spin_some(): 5/5   spin_all(0): 5/5   late subscription: 2 spin_some() call(s)
EventsCBGExecutor        spin_some(): 1/5   spin_all(0): 1/5   late subscription: 3 spin_some() call(s)
```

